PyMODINIT_FUNC
PyInit_wfm_compose (void)
{
  import_array ();
  if (PyType_Ready (&SynthType) < 0)
    return NULL;
  if (PyType_Ready (&SegmentType) < 0)
    return NULL;
  if (PyType_Ready (&TimelineType) < 0)
    return NULL;
  if (PyType_Ready (&ComposerType) < 0)
    return NULL;
  if (PyType_Ready (&ComposerStreamType) < 0)
    return NULL;
  PyObject *m = PyModule_Create (&_moduledef);
  if (!m)
    return NULL;
  Py_INCREF (&SynthType);
  PyModule_AddObject (m, "Synth", (PyObject *)&SynthType);
  Py_INCREF (&SegmentType);
  PyModule_AddObject (m, "Segment", (PyObject *)&SegmentType);
  Py_INCREF (&TimelineType);
  PyModule_AddObject (m, "Timeline", (PyObject *)&TimelineType);
  Py_INCREF (&ComposerType);
  PyModule_AddObject (m, "Composer", (PyObject *)&ComposerType);
  /* gh-1117: adopt dp_interrupt_guard's process-global state from its owner.
   */
  {
    void     *dp_interrupt_guard_state_ptr (void);
    void      dp_interrupt_guard_state_adopt (void *shared);
    PyObject *_own = PyImport_ImportModule ("doppler.interrupt.interrupt");
    if (!_own)
      {
        Py_DECREF (m);
        return NULL;
      }
    PyObject *_pg = PyObject_GetAttrString (_own, "_jm_pg_dp_interrupt_guard");
    Py_DECREF (_own);
    if (!_pg)
      {
        Py_DECREF (m);
        return NULL;
      }
    void *_p = PyCapsule_GetPointer (
        _pg, "doppler.dp_interrupt_guard._jm_procglobal");
    Py_DECREF (_pg);
    if (!_p)
      {
        Py_DECREF (m);
        return NULL;
      }
    dp_interrupt_guard_state_adopt (_p);
  }
  return m;
}
